require 'thread'
require 'json'
require 'securerandom'
require 'fileutils'

module AuditAgent
  class EventStore
    FLUSH_INTERVAL = 5
    MAX_BATCH_SIZE = 100

    def initialize(log_dir:, encryption_key:)
      @log_dir = log_dir
      @encryption_key = encryption_key
      @buffer = []
      @buffer_mutex = Mutex.new
      @sequence_counter = 0
      @counter_mutex = Mutex.new
      @flush_thread = start_flush_thread
      FileUtils.mkdir_p(@log_dir)
    end

    def record_event(event_type:, actor:, resource:, details: {})
      event = build_event(event_type, actor, resource, details)
      validated = validate_and_stamp(event)
      enqueue(validated)
    end

    private

    def build_event(event_type, actor, resource, details)
      {
        id: SecureRandom.uuid,
        type: event_type,
        actor: actor,
        resource: resource,
        details: details,
        created_at: Time.now.utc.iso8601(6)
      }
    end

    def validate_and_stamp(event)
      raise ArgumentError, "Missing event type" unless event[:type]
      raise ArgumentError, "Missing actor" unless event[:actor]
      seq = next_sequence
      event.merge(sequence: seq, integrity_hash: compute_integrity(event, seq))
    end

    def next_sequence
      @counter_mutex.synchronize do
        @sequence_counter += 1
        @sequence_counter
      end
    end

    def compute_integrity(event, seq)
      payload = "#{seq}:#{event[:id]}:#{event[:type]}:#{event[:actor]}:#{event[:resource]}"
      OpenSSL::HMAC.hexdigest('SHA256', @encryption_key, payload)
    end

    def enqueue(event)
      should_flush = false
      @buffer_mutex.synchronize do
        @buffer << event
        should_flush = @buffer.size >= MAX_BATCH_SIZE
      end
      flush_to_disk if should_flush
    end

    def flush_to_disk
      events_to_write = nil
      @buffer_mutex.synchronize do
        events_to_write = @buffer.dup
        @buffer.clear
      end
      return if events_to_write.nil? || events_to_write.empty?
      write_batch(events_to_write)
    end

    def write_batch(events)
      filename = "audit_#{Time.now.utc.strftime('%Y%m%d_%H%M%S')}_#{SecureRandom.hex(4)}.jsonl"
      filepath = File.join(@log_dir, filename)
      File.open(filepath, 'w', 0o600) do |f|
        events.each { |e| f.puts(JSON.generate(e)) }
      end
    end

    def start_flush_thread
      Thread.new do
        loop do
          sleep FLUSH_INTERVAL
          flush_to_disk
        end
      end
    end
  end

  class PolicyEnforcer
    SENSITIVE_ACTIONS = %w[delete_user modify_permissions export_data reset_credentials].freeze

    def initialize(event_store:, approval_cache:)
      @event_store = event_store
      @approval_cache = approval_cache
    end

    def execute_action(actor:, action:, resource:, params: {})
      request_id = SecureRandom.uuid

      if requires_approval?(action)
        approval = check_approval(actor, action, resource, request_id)
        unless approval[:granted]
          @event_store.record_event(
            event_type: 'action_denied',
            actor: actor,
            resource: resource,
            details: { action: action, reason: 'no_approval', request_id: request_id }
          )
          return { success: false, reason: 'approval_required' }
        end
      end

      @event_store.record_event(
        event_type: 'action_executed',
        actor: actor,
        resource: resource,
        details: { action: action, params: params, request_id: request_id }
      )
      { success: true, request_id: request_id }
    end

    private

    def requires_approval?(action)
      SENSITIVE_ACTIONS.include?(action)
    end

    def check_approval(actor, action, resource, request_id)
      cache_key = "#{actor}:#{action}:#{resource}"
      cached = @approval_cache.get(cache_key)
      return cached if cached && !expired?(cached)

      @approval_cache.fetch_and_set(cache_key, actor, action, resource, request_id)
    end

    def expired?(approval)
      Time.now.utc - Time.parse(approval[:granted_at]) > 300
    end
  end

  class ApprovalCache
    def initialize
      @store = {}
      @mutex = Mutex.new
    end

    def get(key)
      @mutex.synchronize { @store[key] }
    end

    def set(key, value)
      @mutex.synchronize { @store[key] = value }
    end

    def fetch_and_set(cache_key, actor, action, resource, request_id)
      approval = query_approval_service(actor, action, resource, request_id)
      set(cache_key, approval)
      approval
    end

    def revoke(actor, action, resource)
      cache_key = "#{actor}:#{action}:#{resource}"
      @mutex.synchronize { @store.delete(cache_key) }
    end

    private

    def query_approval_service(actor, action, resource, request_id)
      # Simulates external approval service call
      sleep(0.1)
      { granted: false, granted_at: Time.now.utc.iso8601, request_id: request_id }
    end
  end

  class AdminInterface
    def initialize(policy_enforcer:, approval_cache:)
      @enforcer = policy_enforcer
      @cache = approval_cache
    end

    def grant_temporary_approval(admin_actor:, target_actor:, action:, resource:)
      cache_key = "#{target_actor}:#{action}:#{resource}"
      approval = {
        granted: true,
        granted_at: Time.now.utc.iso8601,
        granted_by: admin_actor,
        request_id: SecureRandom.uuid
      }
      @cache.set(cache_key, approval)
      approval
    end

    def revoke_approval(target_actor:, action:, resource:)
      @cache.revoke(target_actor, action, resource)
    end
  end
end
